 const added=verified.filter(item=>matchedSet.has(item)),missingVerified=missing.filter(item=>verifiedSet.has(item)),unverified=requested.map(requirement=>requirement.label).filter(item=>!verifiedSet.has(item));
 if(score===null)return{matched,added,missing,missingVerified,unverified,score,status:"Requirements need a manual review",level:"manual"};
 if(score>=90)return{matched,added,missing,missingVerified,unverified,score,status:"Excellent tailored CV match",level:"strong"};
 if(score>=75)return{matched,added,missing,missingVerified,unverified,score,status:"Good match — review the remaining gaps",level:"strong"};
 if(score>=50)return{matched,added,missing,missingVerified,unverified,score,status:"Match needs improvement",level:"partial"};
